CREATE DATABASE IF NOT EXISTS biblioteca CHARACTER SET utf8mb4; USE biblioteca;
CREATE TABLE usuarios(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL,documento VARCHAR(20) NOT NULL UNIQUE,email VARCHAR(120) NOT NULL,username VARCHAR(40) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,rol ENUM('ADMIN','EMPLEADO') NOT NULL);
CREATE TABLE alumnos(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL,documento VARCHAR(20) NOT NULL UNIQUE,email VARCHAR(120) NOT NULL,grupo VARCHAR(30) NOT NULL);
CREATE TABLE libros(id INT AUTO_INCREMENT PRIMARY KEY,titulo VARCHAR(150) NOT NULL,autor VARCHAR(100) NOT NULL,isbn VARCHAR(30) NOT NULL UNIQUE,stock INT NOT NULL CHECK(stock>=0));
CREATE TABLE prestamos(id INT AUTO_INCREMENT PRIMARY KEY,alumno_id INT NOT NULL,libro_id INT NOT NULL,fecha_prestamo DATE NOT NULL,fecha_devolucion DATE NULL,estado ENUM('ACTIVO','DEVUELTO') NOT NULL DEFAULT 'ACTIVO',FOREIGN KEY(alumno_id) REFERENCES alumnos(id),FOREIGN KEY(libro_id) REFERENCES libros(id));